$BODY$;

-- deleteinstancemutationidempotency.sql:
CREATE OR REPLACE FUNCTION storage.deleteinstancemutationidempotency(_createdbefore TIMESTAMPTZ, _batchsize INT)
    RETURNS INT
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _deleteCount INTEGER;
BEGIN
    DELETE FROM storage.instance_mutation_idempotency
        WHERE ctid IN (
            SELECT ctid
            FROM storage.instance_mutation_idempotency
            WHERE created < _createdbefore
            LIMIT _batchsize
        );
    GET DIAGNOSTICS _deleteCount = ROW_COUNT;

    RETURN _deleteCount;
END;
$BODY$;


-- deletemigrationstate.sql:
CREATE OR REPLACE PROCEDURE storage.deletemigrationstate (_instanceguid UUID)
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
	DELETE FROM storage.a1migrationstate WHERE instanceguid = _instanceguid;
	DELETE FROM storage.a2migrationstate WHERE instanceguid = _instanceguid;
END;
$BODY$;

-- deleteorphanblobversions.sql:
CREATE OR REPLACE FUNCTION storage.deleteorphanblobversions(_versions UUID[])
    RETURNS INT
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _deleteCount INTEGER;
BEGIN
    DELETE FROM storage.dataelementblobversions
        WHERE id = ANY(_versions)
            AND detachedat IS NOT NULL;
    GET DIAGNOSTICS _deleteCount = ROW_COUNT;

    RETURN _deleteCount;
END;
$BODY$;


-- diagnoseinstancemutationdeletefailure.sql:
CREATE OR REPLACE PROCEDURE storage.diagnoseinstancemutationdeletefailure(
    _deleteelements JSONB,
    _instanceguid UUID,
    _currentinstanceversion INT,
    _currentprocessstateversion INT,
    _deleteddataelementids UUID[])
LANGUAGE plpgsql
AS $BODY$
DECLARE
    _faileddataelementid UUID;
    _errorcode TEXT;
BEGIN
    WITH targetdataelements AS (
        SELECT *
        FROM (
            SELECT
                deleteelement.ordinality,
                (deleteelement.value ->> 'elementId')::UUID AS dataelementid,
                COALESCE((deleteelement.value ->> 'ignoreLock')::BOOL, false) AS ignorelock
            FROM jsonb_array_elements(_deleteelements) WITH ORDINALITY deleteelement(value, ordinality)
        ) deleteelements
        WHERE NOT COALESCE(
            deleteelements.dataelementid = ANY(_deleteddataelementids),
            false)
    ),
    targetdataelementstates AS (
        SELECT
            targetdataelements.ordinality,
            targetdataelements.dataelementid,
            targetdataelements.ignorelock,
            dataelement.alternateid IS NOT NULL AS targetexists,
            COALESCE((dataelement.element ->> 'Locked')::BOOLEAN, false) AS elementislocked
        FROM targetdataelements
        LEFT JOIN storage.dataelements dataelement
            ON dataelement.instanceguid = _instanceguid
            AND dataelement.alternateid = targetdataelements.dataelementid
    ),
    validationerrors AS (
        SELECT
            targetdataelementstates.ordinality,
            1 AS priority,
            targetdataelementstates.dataelementid,
            'data_element_not_found'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE NOT targetdataelementstates.targetexists

        UNION ALL

        SELECT
            targetdataelementstates.ordinality,
            2 AS priority,
            targetdataelementstates.dataelementid,
            'locked'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE targetdataelementstates.targetexists
            AND NOT targetdataelementstates.ignorelock
            AND targetdataelementstates.elementislocked
    )
    SELECT validationerrors.dataelementid, validationerrors.errorcode
    INTO _faileddataelementid, _errorcode
    FROM validationerrors
    ORDER BY validationerrors.ordinality, validationerrors.priority
    LIMIT 1;

    IF _errorcode IS NOT NULL
    THEN
        CALL storage.raiseinstancemutationerror(
            _errorcode,
            _currentinstanceversion,
            _currentprocessstateversion,
            _faileddataelementid);
        RETURN;
    END IF;

    RAISE EXCEPTION 'Apply instance mutation delete affected fewer data elements than expected, but no failing item could be identified.';
END;
$BODY$;


-- diagnoseinstancemutationupdatefailure.sql:
CREATE OR REPLACE PROCEDURE storage.diagnoseinstancemutationupdatefailure(
    _updateelements JSONB,
    _instanceguid UUID,
    _currentinstanceversion INT,
    _currentprocessstateversion INT,
    _updateddataelementids UUID[])
LANGUAGE plpgsql
AS $BODY$
DECLARE
    _faileddataelementid UUID;
    _errorcode TEXT;
BEGIN
    WITH targetdataelements AS (
        SELECT *
        FROM (
            SELECT
                updateelement.ordinality,
                (updateelement.value ->> 'elementId')::UUID AS dataelementid,
                (updateelement.value ->> 'expectedBlobVersion')::UUID AS expectedblobversion,
                COALESCE((updateelement.value ->> 'ignoreLock')::BOOL, false) AS ignorelock
            FROM jsonb_array_elements(_updateelements) WITH ORDINALITY updateelement(value, ordinality)
        ) updateelements
        WHERE NOT COALESCE(
            updateelements.dataelementid = ANY(_updateddataelementids),
            false)
    ),
    targetdataelementstates AS (
        SELECT
            targetdataelements.ordinality,
            targetdataelements.dataelementid,
            targetdataelements.expectedblobversion,
            targetdataelements.ignorelock,
            dataelement.alternateid IS NOT NULL AS targetexists,
            dataelement.currentblobversion,
            COALESCE((dataelement.element -> 'DeleteStatus' ->> 'IsHardDeleted')::BOOLEAN, false) AS elementisharddeleted,
            COALESCE((dataelement.element ->> 'Locked')::BOOLEAN, false) AS elementislocked
        FROM targetdataelements
        LEFT JOIN storage.dataelements dataelement
            ON dataelement.instanceguid = _instanceguid
            AND dataelement.alternateid = targetdataelements.dataelementid
    ),
    validationerrors AS (
        SELECT
            targetdataelementstates.ordinality,
            1 AS priority,
            targetdataelementstates.dataelementid,
            'data_element_not_found'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE NOT targetdataelementstates.targetexists

        UNION ALL

        SELECT
            targetdataelementstates.ordinality,
            2 AS priority,
            targetdataelementstates.dataelementid,
            'blob_version_mismatch'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE targetdataelementstates.targetexists
            AND targetdataelementstates.expectedblobversion IS NOT NULL
            AND targetdataelementstates.currentblobversion IS DISTINCT FROM targetdataelementstates.expectedblobversion

        UNION ALL

        SELECT
            targetdataelementstates.ordinality,
            3 AS priority,
            targetdataelementstates.dataelementid,
            'data_element_hard_deleted'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE targetdataelementstates.targetexists
            AND targetdataelementstates.elementisharddeleted

        UNION ALL

        SELECT
            targetdataelementstates.ordinality,
            4 AS priority,
            targetdataelementstates.dataelementid,
            'locked'::TEXT AS errorcode
        FROM targetdataelementstates
        WHERE targetdataelementstates.targetexists
            AND NOT targetdataelementstates.ignorelock
            AND targetdataelementstates.elementislocked
    )
    SELECT validationerrors.dataelementid, validationerrors.errorcode
    INTO _faileddataelementid, _errorcode
    FROM validationerrors
    ORDER BY validationerrors.ordinality, validationerrors.priority
    LIMIT 1;

    IF _errorcode IS NOT NULL
    THEN
        CALL storage.raiseinstancemutationerror(
            _errorcode,
            _currentinstanceversion,
            _currentprocessstateversion,
            _faileddataelementid);
        RETURN;
    END IF;

    RAISE EXCEPTION 'Apply instance mutation update affected fewer data elements than expected, but no failing item could be identified.';
END;
$BODY$;


-- filterinstanceevent.sql:
CREATE OR REPLACE FUNCTION storage.filterinstanceevent(_instance UUID, _from TIMESTAMPTZ, _to TIMESTAMPTZ, _eventtype TEXT[])
    RETURNS TABLE (event JSONB)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY 
    SELECT ie.event
    FROM storage.instanceevents ie
    WHERE instance = _instance
        AND (ie.event->>'Created')::TIMESTAMP >= _from
        AND (ie.event->>'Created')::TIMESTAMP <= _to
        AND (_eventtype IS NULL OR ie.event->>'EventType' = ANY (_eventtype))
    ORDER BY ie.event->'Created';
END;
$BODY$;

-- getinstancemetrics.sql:
CREATE OR REPLACE FUNCTION storage.get_instance_metrics(
    day_input integer,
    month_input integer,
    year_input integer)
    RETURNS TABLE (appid TEXT, completed_instances bigint)
    LANGUAGE 'plpgsql'

AS $BODY$
DECLARE
    start_date TIMESTAMPTZ;
BEGIN
    start_date = MAKE_TIMESTAMPTZ(year_input, month_input, day_input, 0, 0, 0, 'UTC');
    RETURN QUERY
        SELECT
            i.appid,
            count(i.id) AS CompletedInstances
        FROM storage.instances i
        WHERE (i.instance -> 'Status' ->> 'IsArchived')::BOOL = TRUE
            AND i.instance -> 'Status' ? 'Archived'
            AND NULLIF(i.instance -> 'Status' ->> 'Archived', '') IS NOT NULL
            AND storage.jsonb_text_to_timestamptz(i.instance, 'Status', 'Archived') >= start_date
            AND storage.jsonb_text_to_timestamptz(i.instance, 'Status', 'Archived') < start_date + INTERVAL '1 day'
            AND i.altinnmainversion = 3
        GROUP BY i.appid;
END;
$BODY$;


