CREATE OR REPLACE FUNCTION storage.reada1migrationstate(_a1archivereference BIGINT)
    RETURNS TABLE (instanceguid UUID)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY 
    SELECT ms.instanceguid FROM storage.a1migrationstate ms WHERE ms.a1archivereference = _a1archivereference;
END;
$BODY$;

-- reada2codelist.sql:
CREATE OR REPLACE FUNCTION storage.reada2codelist(_name TEXT, _language TEXT)
    RETURNS TABLE (codelist TEXT)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY
    SELECT c.codelist FROM storage.a2codelists c
        WHERE name ilike _name AND language = _language
        ORDER BY version DESC LIMIT 1;
END;
$BODY$;

-- reada2image.sql:
CREATE OR REPLACE FUNCTION storage.reada2image(_name TEXT)
    RETURNS TABLE (image BYTEA)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY
    SELECT
        CASE
            WHEN c.image IS NOT NULL THEN c.image
            ELSE (SELECT p.image FROM storage.a2images p WHERE p.id = c.parentid)
        END
    FROM storage.a2images c WHERE c.name = _name; 
END;
$BODY$;

-- reada2migrationstate.sql:
CREATE OR REPLACE FUNCTION storage.reada2migrationstate(_a2archivereference BIGINT)
    RETURNS TABLE (instanceguid UUID)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY 
    SELECT ms.instanceguid FROM storage.a2migrationstate ms WHERE ms.a2archivereference = _a2archivereference;
END;
$BODY$;

-- reada2xsls.sql:
CREATE OR REPLACE FUNCTION storage.reada2xsls(_org TEXT, _app TEXT, _lformid INT, _language TEXT, _xsltype INT)
    RETURNS TABLE (xsl TEXT, isportrait BOOL)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY 
    SELECT
        CASE
            WHEN x.xsl IS NOT NULL THEN x.xsl
            ELSE (SELECT p.xsl FROM storage.a2xsls p WHERE p.id = x.parentid)
        END,
        x.isportrait
        FROM storage.a2xsls x
        WHERE x.org = _org and x.app = _app and x.lformid = _lformid and x.language = _language and x.xsltype = _xsltype
        ORDER BY pagenumber;

END;
$BODY$;

-- readblobversions.sql:
CREATE OR REPLACE FUNCTION storage.readblobversions(_instanceguid UUID, _dataelementid UUID)
    RETURNS TABLE (instanceguid UUID, appid TEXT, blobstorageorg TEXT, storageaccountnumber INT, blobversions UUID[])
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
    RETURN QUERY
        SELECT
            bv.instanceguid,
            bv.appid,
            bv.blobstorageorg,
            bv.storageaccountnumber,
            array_agg(bv.id ORDER BY bv.created, bv.id) AS blobversions
        FROM storage.dataelementblobversions bv
        WHERE bv.instanceguid = _instanceguid
            AND bv.dataelementid = _dataelementid
            AND bv.detachedat IS NULL
        GROUP BY bv.instanceguid, bv.appid, bv.blobstorageorg, bv.storageaccountnumber
        ORDER BY min(bv.created), min(bv.id::TEXT);
END;
$BODY$;


-- readblobversionsforinstance.sql:
CREATE OR REPLACE FUNCTION storage.readblobversionsforinstance(_instanceguid UUID)
    RETURNS TABLE (dataelementid UUID, instanceguid UUID, appid TEXT, blobstorageorg TEXT, storageaccountnumber INT, blobversions UUID[])
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
    RETURN QUERY
        SELECT
            bv.dataelementid,
            bv.instanceguid,
            bv.appid,
            bv.blobstorageorg,
            bv.storageaccountnumber,
            array_agg(bv.id ORDER BY bv.created, bv.id) AS blobversions
        FROM storage.dataelementblobversions bv
        WHERE bv.instanceguid = _instanceguid
            AND bv.detachedat IS NULL
        GROUP BY bv.dataelementid, bv.instanceguid, bv.appid, bv.blobstorageorg, bv.storageaccountnumber
        ORDER BY min(bv.created), min(bv.id::TEXT);
END;
$BODY$;


-- readdataelement.sql:
CREATE OR REPLACE FUNCTION storage.readdataelement_v2(_alternateid UUID)
    RETURNS TABLE (element JSONB, currentblobversion UUID)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY 
    SELECT d.element, d.currentblobversion
    FROM storage.dataelements d
    WHERE d.alternateid = _alternateid;

END;
$BODY$;


-- readdataelementexists.sql:
CREATE OR REPLACE FUNCTION storage.readdataelementexists(_alternateid UUID)
    RETURNS TABLE (element BOOLEAN)
    LANGUAGE 'plpgsql'

AS $BODY$
BEGIN
RETURN QUERY
    SELECT EXISTS (
        SELECT 1
        FROM storage.dataelements de where de.alternateid = _alternateid
    );
END;
$BODY$;


-- readdeletedinstances.sql:
CREATE OR REPLACE FUNCTION storage.readdeletedinstances()
    RETURNS TABLE (instance JSONB)
    LANGUAGE 'plpgsql'
    
AS $BODY$
BEGIN
RETURN QUERY
    -- Make sure that part of the where clause is exactly as in filtered index instances_isharddeleted_and_more
    SELECT i.instance FROM storage.instances i
    WHERE (i.instance -> 'Status' -> 'IsHardDeleted')::BOOLEAN AND
    (
        NOT (i.instance -> 'Status' -> 'IsArchived')::BOOLEAN OR (i.instance -> 'CompleteConfirmations') IS NOT NULL
    )
    -- Keep hard-deleted instance rows past the workflow callback retry window so delete mutations can replay.
    AND (i.instance -> 'Status' ->> 'HardDeleted')::TIMESTAMPTZ <= (NOW() - INTERVAL '7 days')
    AND i.AltinnMainVersion >= 3;
END;
$BODY$;


-- readdetachedblobversions.sql:
CREATE OR REPLACE FUNCTION storage.readdetachedblobversions(_dataelementid UUID)
    RETURNS TABLE (instanceguid UUID, appid TEXT, blobstorageorg TEXT, storageaccountnumber INT, blobversions UUID[])
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
    RETURN QUERY
        SELECT
            bv.instanceguid,
            bv.appid,
            bv.blobstorageorg,
            bv.storageaccountnumber,
            array_agg(bv.id ORDER BY bv.created, bv.id) AS blobversions
        FROM storage.dataelementblobversions bv
        WHERE bv.dataelementid = _dataelementid
            AND bv.detachedat IS NOT NULL
        GROUP BY bv.instanceguid, bv.appid, bv.blobstorageorg, bv.storageaccountnumber
        ORDER BY min(bv.created), min(bv.id::TEXT);
END;
$BODY$;


-- readharddeleteddataelementsforcleanup.sql:
CREATE OR REPLACE FUNCTION storage.readharddeleteddataelementsforcleanup()
    RETURNS TABLE (
        id BIGINT,
        instance JSONB,
        element JSONB,
        blobversioninstanceguid UUID,
        blobversionappid TEXT,
        blobversionblobstorageorg TEXT,
        blobversionstorageaccountnumber INT,
        blobversions UUID[])
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
    -- Force nested loop join to avoid hash join on large instances table
    -- With only a small count of hard-deleted records, nested loop with index lookups is optimal
    SET LOCAL enable_hashjoin = off;
    SET LOCAL enable_mergejoin = off;

    RETURN QUERY
    SELECT
        i.id,
        i.instance,
        d.element,
        v.instanceguid,
        v.appid,
        v.blobstorageorg,
        v.storageaccountnumber,
        COALESCE(v.blobversions, ARRAY[]::UUID[])
    FROM (
        -- Target index dataelements_isharddeleted
        SELECT instanceinternalid, de.alternateid, de.element
        FROM storage.dataelements de
        WHERE (de.element -> 'DeleteStatus' -> 'IsHardDeleted')::BOOLEAN
            AND (de.element -> 'DeleteStatus' ->> 'HardDeleted')::TIMESTAMPTZ <= NOW() - INTERVAL '7 days'
        OFFSET 0  -- Optimization fence: prevents subquery flattening which causes wrong join strategy
    ) d
    JOIN storage.instances i ON i.id = d.instanceinternalid
    LEFT JOIN LATERAL (
        SELECT
            bv.instanceguid,
            bv.appid,
            bv.blobstorageorg,
            bv.storageaccountnumber,
            array_agg(bv.id ORDER BY bv.created, bv.id) AS blobversions
        FROM storage.dataelementblobversions bv
        WHERE bv.instanceguid = i.alternateid
            AND bv.dataelementid = d.alternateid
            AND bv.detachedat IS NULL
        GROUP BY bv.instanceguid, bv.appid, bv.blobstorageorg, bv.storageaccountnumber
    ) v ON TRUE
    WHERE i.AltinnMainVersion >= 3;
END;
$BODY$;


-- readinstance.sql:
CREATE OR REPLACE FUNCTION storage.readinstance_v2(_alternateid UUID)
    RETURNS TABLE (id BIGINT, instance JSONB, instanceversion INT, processstateversion INT, element JSONB, currentblobversion UUID)
    LANGUAGE 'plpgsql'

AS $BODY$
BEGIN
RETURN QUERY
    SELECT i.id, i.instance, i.instance_version, i.process_state_version, d.element, d.currentblobversion FROM storage.instances i
        LEFT JOIN storage.dataelements d ON i.id = d.instanceinternalid
        WHERE i.alternateid = _alternateid
        ORDER BY d.id;

END;
$BODY$;


