$BODY$;

-- updatedataelement_filescanstatus.sql:
CREATE OR REPLACE FUNCTION storage.updatedataelement_filescanstatus(
    _dataelementGuid UUID,
    _instanceGuid UUID,
    _elementChanges JSONB,
    _expectedcurrentblobversion UUID)
    RETURNS TABLE (updatedElement JSONB, currentblobversion UUID, instanceversion INT, processstateversion INT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _currentInstanceVersion INT;
    _currentProcessStateVersion INT;
    _dataElementCurrentBlobVersion UUID;
BEGIN
    SELECT
        i.instance_version,
        i.process_state_version
        INTO _currentInstanceVersion, _currentProcessStateVersion
        FROM storage.instances i
        WHERE i.alternateid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, NULL::INT, NULL::INT, 'not_found'::TEXT;
        RETURN;
    END IF;

    SELECT d.currentblobversion
        INTO _dataElementCurrentBlobVersion
        FROM storage.dataelements d
        WHERE d.alternateid = _dataelementGuid AND d.instanceguid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF _expectedcurrentblobversion IS NOT NULL AND _dataElementCurrentBlobVersion IS DISTINCT FROM _expectedcurrentblobversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, 'version_mismatch'::TEXT;
        RETURN;
    END IF;

    RETURN QUERY
        UPDATE storage.dataelements
            SET element = element || _elementChanges
            WHERE alternateid = _dataelementGuid AND instanceguid = _instanceGuid
            RETURNING element, storage.dataelements.currentblobversion, _currentInstanceVersion, _currentProcessStateVersion, 'ok'::TEXT;
END;
$BODY$;


-- updatedataelement_lockstatus.sql:
CREATE OR REPLACE FUNCTION storage.updatedataelement_lockstatus(
    _dataelementGuid UUID,
    _instanceGuid UUID,
    _locked BOOL)
    RETURNS TABLE (updatedElement JSONB, currentblobversion UUID, instanceversion INT, processstateversion INT, currentprocessstatus TEXT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _currentInstanceVersion INT;
    _currentProcessStateVersion INT;
    _currentProcessStatus TEXT;
BEGIN
    SELECT
        i.instance_version,
        i.process_state_version,
        COALESCE(i.instance -> 'Process' ->> 'Status', 'idle')
        INTO _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus
        FROM storage.instances i
        WHERE i.alternateid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, NULL::INT, NULL::INT, NULL::TEXT, 'not_found'::TEXT;
        RETURN;
    END IF;

    PERFORM 1
        FROM storage.dataelements d
        WHERE d.alternateid = _dataelementGuid AND d.instanceguid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF _currentProcessStatus <> 'idle'
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'process_status_conflict'::TEXT;
        RETURN;
    END IF;

    RETURN QUERY
        UPDATE storage.dataelements
            SET element = element || jsonb_build_object('Locked', _locked)
            WHERE alternateid = _dataelementGuid AND instanceguid = _instanceGuid
            RETURNING element, storage.dataelements.currentblobversion, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'ok'::TEXT;
END;
$BODY$;


-- updatedataelement_readstatus.sql:
CREATE OR REPLACE FUNCTION storage.updatedataelement_readstatus(
    _dataelementGuid UUID,
    _instanceGuid UUID,
    _isRead BOOL)
    RETURNS TABLE (updatedElement JSONB, currentblobversion UUID, instanceversion INT, processstateversion INT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _currentInstanceVersion INT;
    _currentProcessStateVersion INT;
    _updatedElement JSONB;
    _currentBlobVersion UUID;
BEGIN
    SELECT i.instance_version, i.process_state_version
        INTO _currentInstanceVersion, _currentProcessStateVersion
        FROM storage.instances i
        WHERE i.alternateid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, NULL::INT, NULL::INT, 'not_found'::TEXT;
        RETURN;
    END IF;

    UPDATE storage.dataelements
        SET element = element || jsonb_build_object('IsRead', _isRead)
        WHERE alternateid = _dataelementGuid AND instanceguid = _instanceGuid
        RETURNING element, storage.dataelements.currentblobversion
            INTO _updatedElement, _currentBlobVersion;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF _isRead = FALSE
    THEN
        UPDATE storage.instances
            SET instance = jsonb_set(instance, '{Status, ReadStatus}', '0')
            WHERE alternateid = _instanceGuid
                AND instance -> 'Status' ->> 'ReadStatus' = '1'
                AND NOT EXISTS (
                    SELECT 1 FROM storage.dataelements
                        WHERE element -> 'IsRead' = 'true'
                            AND instanceguid = _instanceGuid
                            AND alternateid <> _dataelementGuid
                );
    END IF;

    RETURN QUERY SELECT _updatedElement, _currentBlobVersion, _currentInstanceVersion, _currentProcessStateVersion, 'ok'::TEXT;
END;
$BODY$;


-- updatedataelement.sql:
CREATE OR REPLACE FUNCTION storage.updatedataelement_v3(
    _dataelementGuid UUID,
    _instanceGuid UUID,
    _elementChanges JSONB,
    _instanceChanges JSONB,
    _isReadChangedToFalse BOOL,
    _lastChanged TIMESTAMPTZ,
    _newcurrentblobversion UUID,
    _expectedcurrentblobversion UUID,
    _ignoreLock BOOL,
    _expectedinstanceversion INT DEFAULT NULL,
    _expectedprocessstateversion INT DEFAULT NULL)
    RETURNS TABLE (updatedElement JSONB, currentblobversion UUID, instanceversion INT, processstateversion INT, currentprocessstatus TEXT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _lastChanged6digits TEXT;
    _instanceIsHardDeleted BOOL;
    _currentInstanceVersion INT;
    _currentProcessStateVersion INT;
    _currentProcessStatus TEXT;
    _newInstanceVersion INT;
    _dataElementIsHardDeleted BOOL;
    _dataElementIsLocked BOOL;
    _dataElementCurrentBlobVersion UUID;
BEGIN
    SELECT
        COALESCE((i.instance -> 'Status' ->> 'IsHardDeleted')::BOOLEAN, FALSE),
        i.instance_version,
        i.process_state_version,
        COALESCE(i.instance -> 'Process' ->> 'Status', 'idle')
        INTO _instanceIsHardDeleted, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus
        FROM storage.instances i
        WHERE i.alternateid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, NULL::INT, NULL::INT, NULL::TEXT, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF _expectedinstanceversion IS NOT NULL AND _currentInstanceVersion <> _expectedinstanceversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'instance_version_mismatch'::TEXT;
        RETURN;
    END IF;

    IF _expectedprocessstateversion IS NOT NULL AND _currentProcessStateVersion <> _expectedprocessstateversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'process_state_version_mismatch'::TEXT;
        RETURN;
    END IF;

    IF _instanceIsHardDeleted
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'hard_deleted'::TEXT;
        RETURN;
    END IF;

    SELECT COALESCE((d.element -> 'DeleteStatus' ->> 'IsHardDeleted')::BOOLEAN, FALSE),
        COALESCE((d.element ->> 'Locked')::BOOLEAN, FALSE),
        d.currentblobversion
        INTO _dataElementIsHardDeleted, _dataElementIsLocked, _dataElementCurrentBlobVersion
        FROM storage.dataelements d
        WHERE d.alternateid = _dataelementGuid AND d.instanceguid = _instanceGuid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF _expectedcurrentblobversion IS NOT NULL AND _dataElementCurrentBlobVersion IS DISTINCT FROM _expectedcurrentblobversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'version_mismatch'::TEXT;
        RETURN;
    END IF;

    IF _dataElementIsHardDeleted
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'hard_deleted'::TEXT;
        RETURN;
    END IF;

    IF NOT _ignoreLock AND _dataElementIsLocked
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'locked'::TEXT;
        RETURN;
    END IF;

    IF _lastChanged IS NOT NULL
    THEN
        -- Make sure that lastChanged has the Postgres precision (6 digits). The timestamp from C# DateTime and then json serialize has 7 digits
        _lastChanged6digits = REPLACE((_lastChanged AT TIME ZONE 'UTC')::TEXT, ' ', 'T') || 'Z';
        _elementChanges := _elementChanges || jsonb_set('{"LastChanged":""}', '{LastChanged}', to_jsonb(_lastChanged6digits));
    END IF;

    IF _currentProcessStatus <> 'idle'
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::UUID, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'process_status_conflict'::TEXT;
        RETURN;
    END IF;

    IF _newcurrentblobversion IS NOT NULL
    THEN
        -- Only one version per data element may be attached, and the partial unique index
        -- enforcing that is checked per statement, so the predecessor is detached first.
        UPDATE storage.dataelementblobversions
            SET detachedat = NOW()
            WHERE instanceguid = _instanceGuid
                AND dataelementid = _dataelementGuid
                AND detachedat IS NULL;

        UPDATE storage.dataelementblobversions
            SET detachedat = NULL
            WHERE id = _newcurrentblobversion
                AND instanceguid = _instanceGuid
                AND dataelementid = _dataelementGuid
                AND detachedat IS NOT NULL;
    END IF;

    UPDATE storage.instances
        SET lastchanged = COALESCE(_lastChanged, lastchanged),
            instance_version = instance_version + 1,
            instance = (
                CASE
                    WHEN _isReadChangedToFalse = true AND
                        (SELECT COUNT(*) FROM storage.dataelements
                            WHERE element -> 'IsRead' = 'true' AND instanceguid = _instanceGuid AND alternateid <> _dataelementGuid) = 0
                        AND instance -> 'Status' ->> 'ReadStatus' = '1'
                    THEN jsonb_set(instance, '{Status, ReadStatus}', '0')
                    ELSE instance
                END
            )
            || CASE
                WHEN _lastChanged IS NOT NULL
                THEN _instanceChanges || jsonb_set('{"LastChanged":""}', '{LastChanged}', to_jsonb(_lastChanged6digits))
                ELSE '{}'::JSONB
            END
        WHERE alternateid = _instanceGuid
        RETURNING storage.instances.instance_version INTO _newInstanceVersion;

    RETURN QUERY
        UPDATE storage.dataelements
            SET element = element || _elementChanges,
                currentblobversion = COALESCE(_newcurrentblobversion, storage.dataelements.currentblobversion)
            WHERE alternateid = _dataelementGuid AND instanceguid = _instanceGuid
            RETURNING element, storage.dataelements.currentblobversion, _newInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'ok'::TEXT;
END;
$BODY$;


-- updateinstance_readstatus.sql:
CREATE OR REPLACE FUNCTION storage.updateinstance_readstatus(
        _alternateid UUID,
        _readstatus INT)
    RETURNS TABLE (updatedInstance JSONB, instanceversion INT, processstateversion INT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
    RETURN QUERY
        UPDATE storage.instances SET
            instance = jsonb_set(
                instance,
                '{Status}',
                CASE WHEN jsonb_typeof(instance -> 'Status') = 'object' THEN
                    instance -> 'Status' || jsonb_build_object('ReadStatus', _readstatus)
                ELSE
                    jsonb_build_object('ReadStatus', _readstatus)
                END
            )
        WHERE _alternateid = alternateid
        RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, 'ok'::TEXT;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::INT, NULL::INT, 'not_found'::TEXT;
    END IF;
END;
$BODY$;


-- updateinstance.sql:
CREATE OR REPLACE FUNCTION storage.updateinstance_v4(
        _alternateid UUID,
        _toplevelsimpleprops JSONB,
        _datavalues JSONB,
        _completeconfirmations JSONB,
        _presentationtexts JSONB,
        _status JSONB,
        _substatus JSONB,
        _process JSONB,
        _lastchanged TIMESTAMPTZ,
        _taskid TEXT,
        _confirmed BOOLEAN DEFAULT NULL,
        _expectedinstanceversion INT DEFAULT NULL,
        _expectedprocessstateversion INT DEFAULT NULL)
    RETURNS TABLE (updatedInstance JSONB, instanceversion INT, processstateversion INT, currentprocessstatus TEXT, result TEXT)
    LANGUAGE 'plpgsql'
AS $BODY$
DECLARE
    _currentInstance JSONB;
    _currentInstanceVersion INT;
    _currentProcessStateVersion INT;
    _currentProcessStatus TEXT;
BEGIN
    SELECT i.instance, i.instance_version, i.process_state_version
        INTO _currentInstance, _currentInstanceVersion, _currentProcessStateVersion
        FROM storage.instances i
        WHERE i.alternateid = _alternateid
        FOR UPDATE;

    IF NOT FOUND
    THEN
        RETURN QUERY SELECT NULL::JSONB, NULL::INT, NULL::INT, NULL::TEXT, 'not_found'::TEXT;
        RETURN;
    END IF;

    _currentProcessStatus := COALESCE(_currentInstance -> 'Process' ->> 'Status', 'idle');

    IF _expectedinstanceversion IS NOT NULL AND _currentInstanceVersion <> _expectedinstanceversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'instance_version_mismatch'::TEXT;
        RETURN;
    END IF;

    IF _expectedprocessstateversion IS NOT NULL AND _currentProcessStateVersion <> _expectedprocessstateversion
    THEN
        RETURN QUERY SELECT NULL::JSONB, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'process_state_version_mismatch'::TEXT;
        RETURN;
    END IF;

    IF _currentProcessStatus <> 'idle'
    THEN
        RETURN QUERY SELECT NULL::JSONB, _currentInstanceVersion, _currentProcessStateVersion, _currentProcessStatus, 'process_status_conflict'::TEXT;
        RETURN;
    END IF;

    _toplevelsimpleprops := COALESCE(_toplevelsimpleprops, '{}'::JSONB) - 'Process';

    IF _datavalues IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance || _toplevelsimpleprops ||
                    jsonb_strip_nulls(
                        jsonb_set(
                            '{"DataValues":""}',
                            '{DataValues}',
                            CASE WHEN instance -> 'DataValues' IS NOT NULL THEN
                                instance -> 'DataValues' || _datavalues
                            ELSE
                                _datavalues
                            END
                        )
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _presentationtexts IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance || _toplevelsimpleprops ||
                    jsonb_strip_nulls(
                        jsonb_set(
                            '{"PresentationTexts":""}',
                            '{PresentationTexts}',
                            CASE WHEN instance -> 'PresentationTexts' IS NOT NULL THEN
                                instance -> 'PresentationTexts' || _presentationtexts
                            ELSE
                                _presentationtexts
                            END
                        )
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _completeconfirmations IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance || _toplevelsimpleprops ||
                    jsonb_set(
                        '{"CompleteConfirmations":""}',
                        '{CompleteConfirmations}',
                        CASE WHEN instance -> 'CompleteConfirmations' IS NOT NULL THEN
                            instance -> 'CompleteConfirmations' || _completeconfirmations
                        ELSE
                            _completeconfirmations
                        END
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _status IS NOT NULL AND _process IS NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance ||
                    jsonb_set(
                        instance || _toplevelsimpleprops,
                        '{Status}',
                        CASE WHEN instance -> 'Status' IS NOT NULL THEN
                            instance -> 'Status' || _status
                        ELSE
                            _status
                        END
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _substatus IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance ||
                    jsonb_set(
                        instance || _toplevelsimpleprops,
                        '{Status, Substatus}',
                        jsonb_strip_nulls(_substatus)
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _process IS NOT NULL AND _status IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance ||
                    jsonb_set(
                        instance || _toplevelsimpleprops,
                        '{Process}',
                        jsonb_strip_nulls(_process)
                    ) ||
                    jsonb_set(
                        '{"Status":""}',
                        '{Status}',
                        CASE WHEN instance -> 'Status' IS NOT NULL THEN
                            instance -> 'Status' || _status
                        ELSE
                            _status
                        END
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                process_state_version = process_state_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END,
                taskid = _taskid
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSIF _process IS NOT NULL THEN
        RETURN QUERY
            UPDATE storage.instances SET
                instance = instance ||
                    jsonb_set(
                        instance || _toplevelsimpleprops,
                        '{Process}',
                        jsonb_strip_nulls(_process)
                    ),
                lastchanged = _lastchanged,
                instance_version = instance_version + 1,
                process_state_version = process_state_version + 1,
                confirmed = CASE WHEN _confirmed IS NULL THEN confirmed ELSE _confirmed END,
                taskid = _taskid
            WHERE _alternateid = alternateid
            RETURNING instance, storage.instances.instance_version, storage.instances.process_state_version, _currentProcessStatus, 'ok'::TEXT;
    ELSE
        RAISE EXCEPTION 'Unexpected parameters to update instance';
    END IF;
END;
$BODY$;


-- updateinstancelock.sql:
CREATE OR REPLACE PROCEDURE storage.updateinstancelock(
    _id BIGINT,
    _instanceinternalid BIGINT,
    _ttl INTERVAL,
    _secrethash BYTEA,
    INOUT _result TEXT DEFAULT NULL
)
LANGUAGE plpgsql
AS $BODY$
DECLARE
    _locked_until TIMESTAMPTZ;
    _stored_hash BYTEA;
    _now TIMESTAMPTZ;
BEGIN
    PERFORM pg_advisory_xact_lock(_instanceinternalid);

    SELECT lockeduntil, secrethash FROM storage.instancelocks
    WHERE id = _id
    AND instanceinternalid = _instanceinternalid
    INTO _locked_until, _stored_hash;

    IF _locked_until IS null THEN
        _result := 'lock_not_found';
        RETURN;
    END IF;

    IF _stored_hash != _secrethash THEN
        _result := 'token_mismatch';
        RETURN;
    END IF;

    SELECT clock_timestamp()
    INTO _now;

    IF _locked_until <= _now THEN
        _result := 'lock_expired';
        RETURN;
    END IF;

    UPDATE storage.instancelocks
    SET lockeduntil = _now + _ttl
    WHERE id = _id;

    _result := 'ok';
END;
$BODY$;


-- updatemigrationstatecompleted.sql:
CREATE OR REPLACE PROCEDURE storage.updatemigrationstatecompleted (_instanceguid UUID)
    LANGUAGE 'plpgsql'
AS $BODY$
BEGIN
	UPDATE storage.a1migrationstate SET completed = now()
		WHERE instanceguid = _instanceguid;
	UPDATE storage.a2migrationstate SET completed = now()
		WHERE instanceguid = _instanceguid;
END;
$BODY$;

